package shared

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"strings"
	"testing"
	"time"
)

// The same Islamic civil anchors are pinned in mobile's jalali-selftest and
// web's customer-dates.test. These are calendar boundaries, including the
// extra Dhu al-Hijjah day in a leap year, not values generated by this code.
func TestQamariBillDateAndInlineGoldens(t *testing.T) {
	at := func(y int, m time.Month, d int) int64 {
		return time.Date(y, m, d, 12, 0, 0, 0, kabulTZ).UnixMilli()
	}
	cases := []struct {
		MS int64  `json:"ms"`
		En string `json:"en"`
		Fa string `json:"fa"`
	}{
		{at(2026, time.August, 5), "20 Safar 1448", "۲۰ صفر ۱۴۴۸"},
		{at(2026, time.March, 21), "2 Shawwal 1447", "۲ شوال ۱۴۴۷"},
		{at(2026, time.December, 31), "21 Rajab 1448", "۲۱ رجب ۱۴۴۸"},
		{at(2026, time.June, 16), "30 Dhu al-Hijjah 1447", "۳۰ ذوالحجه ۱۴۴۷"},
		{at(2026, time.June, 17), "1 Muharram 1448", "۱ محرم ۱۴۴۸"},
		{at(2024, time.July, 7), "30 Dhu al-Hijjah 1445", "۳۰ ذوالحجه ۱۴۴۵"},
		{at(2024, time.July, 8), "1 Muharram 1446", "۱ محرم ۱۴۴۶"},
		{at(622, time.July, 19), "1 Muharram 1", "۱ محرم ۱"},
		{at(622, time.July, 18), "18 Jul 622", "۱۸ جولای ۶۲۲"},
	}
	for _, tc := range cases {
		if got := billDate(tc.MS, false, "qamari"); got != tc.En {
			t.Errorf("English Qamari at %d: got %q, want %q", tc.MS, got, tc.En)
		}
		if got := billDate(tc.MS, true, "qamari"); got != tc.Fa {
			t.Errorf("Dari Qamari at %d: got %q, want %q", tc.MS, got, tc.Fa)
		}
	}
	if hy, hm, hd, ok := toQamari(622, 7, 19); !ok || hy != 1 || hm != 1 || hd != 1 {
		t.Fatalf("Friday epoch got %d/%d/%d, ok=%v", hy, hm, hd, ok)
	}
	if _, _, _, ok := toQamari(622, 7, 18); ok {
		t.Fatal("a date before the epoch must use Gregorian fallback")
	}
	if got := billDate(0, false, "qamari"); got != "" {
		t.Errorf("missing generated_at must have no preview date: got %q", got)
	}

	// Execute the ACTUAL inline JS so a typo/escaping discrepancy in the SSR
	// renderer is caught, rather than checking only the parallel Go arithmetic.
	node, err := exec.LookPath("node")
	if err != nil {
		t.Skip("Node is required to verify inline Qamari formatting")
	}
	start := strings.Index(viewHTML, "  var AFM=")
	end := strings.Index(viewHTML, "  function fmtAmt(")
	if start < 0 || end <= start {
		t.Fatal("inline bill date block not found")
	}
	encoded, err := json.Marshal(cases)
	if err != nil {
		t.Fatal(err)
	}
	program := "var calendar='qamari',rtl=false;\n" + viewHTML[start:end] + "\nvar cases=" + string(encoded) + `;
for(var tc of cases){
  rtl=false;if(fmtDate(tc.ms)!==tc.en) throw new Error('English SSR date '+fmtDate(tc.ms)+' != '+tc.en);
  rtl=true;if(fmtDate(tc.ms)!==tc.fa) throw new Error('Dari SSR date '+fmtDate(tc.ms)+' != '+tc.fa);
}
if(fmtDate(NaN)!=='') throw new Error('Invalid SSR date must be blank');
var epoch=new Date(0);epoch.setFullYear(622,6,19);epoch.setHours(12,0,0,0);
rtl=false;if(fmtDate(epoch.getTime())!=='1 Muharram 1') throw new Error('SSR epoch');
epoch.setDate(18);if(fmtDate(epoch.getTime())!=='18 Jul 622') throw new Error('SSR pre-epoch fallback');
`
	cmd := exec.Command(node, "--input-type=commonjs")
	cmd.Env = append(os.Environ(), "TZ=Asia/Kabul")
	cmd.Stdin = strings.NewReader(program)
	var output bytes.Buffer
	cmd.Stdout, cmd.Stderr = &output, &output
	if err := cmd.Run(); err != nil {
		t.Fatalf("inline Qamari bill checks failed: %v\n%s", err, output.String())
	}
}
